/usr/bin/bash -lc 'verified_stream() { for id in f9cad7b01a4721358652a006ce3bab0a f9cad7b01a472135188ff58b5e9727a4 f9cad7b01a47213566955dcd53b862bb f9cad7b01a4721351822d8f19955bf33; do curl -fsS -H "x-api-key: $GALAXY_API_KEY" "$GALAXY_URL/api/datasets/$id/display" | awk -F '"'\\t' 'NR>1 && "'$20=="Yes" {print $1}'"'; done | sort -u; }
pairs_stream() {
  {
    awk -F '\\t' 'NR==FNR {v["'$1]=1; next} FNR==1 {for(i=1;i<=NF;i++){if($i=="Sequence")s=i; if($i=="Protein(s)")p=i}; next} v[$s] {n=split($p,a,/[;,]/); for(j=1;j<=n;j++){gsub(/''^[[:space:]]+|[[:space:]]+$/,"",a[j]); m=split(a[j],b,"|"); id=(m>=3?b[2]:a[j]); if(id!="") print $s "'"\\t\" id}}' <(verified_stream) data/inputs/sgps_peptide_report/SGPS_peptide-report.tabular
    awk -F '\\t' 'NR==FNR {v["'$1]=1; next} FNR==1 {for(i=1;i<=NF;i++){if($i=="Sequence")s=i; if($i=="Proteins")p=i}; next} v[$s] {n=split($p,a,";"); for(j=1;j<=n;j++){gsub(/''^[[:space:]]+|[[:space:]]+$/,"",a[j]); m=split(a[j],b,"|"); id=(m>=3?b[2]:a[j]); if(id!="") print $s "'"\\t\" id}}' <(verified_stream) data/inputs/maxquant_peptide_report/MaxQuant-peptide-report.tabular
  } | sort -u
}
echo \"counts\"
printf 'verified_peptides\\t'; verified_stream | wc -l
printf 'mapped_peptides\\t'; pairs_stream | cut -f1 | sort -u | wc -l
printf 'peptide_protein_pairs\\t'; pairs_stream | wc -l
echo \"unmapped\"
comm -23 <(verified_stream) <(pairs_stream | cut -f1 | sort -u)
echo \"pairs\"
pairs_stream"

